customOutputs.expression:
a!localVariables(
  local!gestiones: a!defaultValue(rule!SCA2_consultarUltimaGestionREST(nuuma: index(index(pv!sol, "datosPerfilesPca", null), "nuuma", null)), {}),
  local!pos: if(
    a!isNullOrEmpty(local!gestiones),
    {},
    wherecontains(
      tostring(pv!idSolicitud),
      touniformstring(a!forEach(items: local!gestiones, expression: tostring(index(fv!item, "numSolicitud", ""))))
    )
  ),
  tostring(
    if(
      a!isNullOrEmpty(local!pos),
      index(index(local!gestiones, 1, null), "numGestion", ""),
      index(index(local!gestiones, index(local!pos, count(local!pos), null), null), "numGestion", "")
    )
  )
)

/* R23-A (duda #3 analista): las 24 h cuentan desde la respuesta de autorización/rechazo (ESTADO/DESBLOQUEO informados), no desde el alta en ANL */
a!localVariables(
  local!anl: index(rule!ANL_getAnulacionByFilter_qr(idSolicitud: pv!idSolicitud), 1, null),
  if(
    or(a!isNotNullOrEmpty(index(local!anl, 'recordType!{5d975d44-07f7-435f-9ffc-947cfdff459d}ANL Anulacion.fields.{95c5de20-8c1b-4a92-9a6f-692b815be505}ESTADO', null)), a!isNotNullOrEmpty(index(local!anl, 'recordType!{5d975d44-07f7-435f-9ffc-947cfdff459d}ANL Anulacion.fields.{b7f65fae-2936-4ce8-a0ae-d98d4bbcc27a}DESBLOQUEO_ANULACION', null))),
    a!defaultValue(pv!contadorRespuestaAnl, 0) + 1,
    0
  )
)

conditions.expression:
/* R23-A (duda #3 analista): SCA2 reanuda sólo cuando ANL ha concluido el ciclo completo (CONCLUIDA), como SCA («Desbloquear proceso principal») */
and(
  or(a!isNotNullOrEmpty(pv!desbloqueoAnulacion), a!isNotNullOrEmpty(pv!estadoAnl)),
  a!defaultValue(pv!concluidaAnl, false) = true
)

/* R46-B (analista, «ANL CONCLUIDA en PRE»): un rechazo (ESTADO informado distinto de 1) no espera a CONCLUIDA; se actualiza la mecanización en CORE con estado 4, cerrada sin mecanizar (póliza vigente) */
and(
  a!isNotNullOrEmpty(pv!estadoAnl),
  tostring(pv!estadoAnl) <> "1"
)

