/* R44-A: como SCA, la anulación que viene de una Acción Administrativa no induce VERTI/Vencimiento */ and(not(rule!SCA2_vieneDeAccionAdministrativa(idSolicitud: pv!idSolicitud)), /* R27-C (22/10): paridad SCA_Mecanizacion: la inducción CMP (331→332→330→333) se ejecuta DESPUÉS de guardarMecanizacion (8) y del alta ANL (300/301), y antes de la espera ANL/cierre (324); antes iba antes del nodo 8. */
/* R24 (analista, doc 45 / duda #1): inducir a Verti siempre que el contacto (determinarContacto, nodo 16) sea VERTI y/o VENCIMIENTO y se mecanice, con independencia del switch vertiSuscripcionInteligente y de la pantalla de casillas (paridad SCA_Mecanizacion nodo 27). Ronda 23-A. */
a!localVariables(
  local!lista: a!defaultValue(index(pv!contacto, "listaContactos", {}), {}),
  if(
    a!isNullOrEmpty(local!lista),
    false,
    or(
      a!forEach(
        items: local!lista,
        expression: or(
          tostring(index(fv!item, "codContacto", "")) = "VERTI",
          tostring(index(fv!item, "codContacto", "")) = "VENCIMIENTO"
        )
      )
    )
  )
))

